# A Consensus Core in Go: Raft, Paxos, and Zab Side by Side

This section builds the core decision logic for three protocols on Kestrel's 5-node cluster. It is a teaching sketch, not production code. It omits timers, networking, snapshots, and membership changes, and it does not run a real election loop. What it does include is the logic that carries the safety guarantees: the vote check, the log-matching check, the commit rule, Paxos value adoption, and Zab history selection.

The code uses the Go standard library only. Node IDs match Kestrel's layout.

## The Raft Core

```go
package consensus

import (
	"errors"
	"sync"
)

type Role int

const (
	Follower Role = iota
	Candidate
	Leader
)

var ErrNotLeader = errors.New("not leader")

// Entry is one ledger operation. Index equals its position in the log;
// the sentinel at index 0 has Term 0.
type Entry struct {
	Term        uint64
	Index       uint64
	IdemKey     string
	Account     string
	AmountCents int64
}

// Store must make writes durable before returning. Acknowledging a vote or
// entry that is later lost in a crash can let one node vote twice in a term.
type Store interface {
	Save(term uint64, votedFor string, log []Entry) error
}

type VoteRequest struct {
	Term, LastLogIndex, LastLogTerm uint64
	CandidateID                     string
}

type AppendRequest struct {
	Term, PrevLogIndex, PrevLogTerm, LeaderCommit uint64
	LeaderID                                      string
	Entries                                       []Entry
}

type Node struct {
	mu          sync.Mutex
	id          string
	peers       []string // every other node in the cluster
	store       Store
	role        Role
	currentTerm uint64
	votedFor    string
	log         []Entry
	commitIndex uint64
	matchIndex  map[string]uint64 // leader only: highest index known stored on each peer
}

// NewNode builds a Kestrel node. For us-east-1 the peers are the other four:
// NewNode("us-east-1", []string{"us-east-2", "eu-west-1", "eu-west-2", "ap-south-1"}, store)
func NewNode(id string, peers []string, s Store) *Node {
	return &Node{
		id:         id,
		peers:      peers,
		store:      s,
		log:        []Entry{{}},
		matchIndex: make(map[string]uint64),
	}
}

// quorum is a strict majority of the whole cluster, including this node.
// For Kestrel's 5 nodes it is 3.
func (n *Node) quorum() int { return (len(n.peers)+1)/2 + 1 }

func (n *Node) last() (index, term uint64) {
	e := n.log[len(n.log)-1]
	return e.Index, e.Term
}

func (n *Node) persist() error {
	return n.store.Save(n.currentTerm, n.votedFor, n.log)
}

// observeTerm adopts a higher term and steps down. Callers hold n.mu.
func (n *Node) observeTerm(term uint64) {
	if term > n.currentTerm {
		n.currentTerm = term
		n.votedFor = ""
		n.role = Follower
	}
}

// HandleRequestVote grants at most one vote per term, and only to a
// candidate whose log is at least as up to date as ours (Raft §5.4.1).
func (n *Node) HandleRequestVote(req VoteRequest) (uint64, bool, error) {
	n.mu.Lock()
	defer n.mu.Unlock()

	n.observeTerm(req.Term)
	if req.Term < n.currentTerm {
		return n.currentTerm, false, nil
	}
	lastIdx, lastTerm := n.last()
	upToDate := req.LastLogTerm > lastTerm ||
		(req.LastLogTerm == lastTerm && req.LastLogIndex >= lastIdx)
	if !upToDate || (n.votedFor != "" && n.votedFor != req.CandidateID) {
		return n.currentTerm, false, nil
	}
	n.votedFor = req.CandidateID
	// The vote must be durable before the reply leaves this node.
	if err := n.persist(); err != nil {
		return n.currentTerm, false, err
	}
	return n.currentTerm, true, nil
}

// HandleAppendEntries enforces Log Matching: an entry is accepted only if
// the entry before it agrees on index and term. Conflicting suffixes are
// truncated, and only genuinely new entries are appended.
func (n *Node) HandleAppendEntries(req AppendRequest) (uint64, bool, error) {
	n.mu.Lock()
	defer n.mu.Unlock()

	n.observeTerm(req.Term)
	if req.Term < n.currentTerm {
		return n.currentTerm, false, nil
	}
	n.role = Follower

	if req.PrevLogIndex >= uint64(len(n.log)) ||
		n.log[req.PrevLogIndex].Term != req.PrevLogTerm {
		return n.currentTerm, false, nil
	}
	for i, e := range req.Entries {
		idx := req.PrevLogIndex + 1 + uint64(i)
		if idx < uint64(len(n.log)) {
			if n.log[idx].Term == e.Term {
				continue // already have it
			}
			n.log = n.log[:idx] // conflict: discard our suffix
		}
		n.log = append(n.log, e)
	}
	if req.LeaderCommit > n.commitIndex {
		lastNew := req.PrevLogIndex + uint64(len(req.Entries))
		n.commitIndex = min(req.LeaderCommit, lastNew)
	}
	if err := n.persist(); err != nil {
		return n.currentTerm, false, err
	}
	return n.currentTerm, true, nil
}

// Propose is called on the leader. It appends a ledger operation; the
// entry is committed only after advanceCommit sees a majority store it.
func (n *Node) Propose(key, account string, cents int64) (uint64, error) {
	n.mu.Lock()
	defer n.mu.Unlock()

	if n.role != Leader {
		return 0, ErrNotLeader
	}
	idx := uint64(len(n.log))
	n.log = append(n.log, Entry{
		Term: n.currentTerm, Index: idx,
		IdemKey: key, Account: account, AmountCents: cents,
	})
	return idx, n.persist()
}

// advanceCommit moves commitIndex forward only for entries from the current
// term that a majority stores (Raft §5.4.2). Callers hold n.mu.
func (n *Node) advanceCommit() {
	lastIdx, _ := n.last()
	for idx := n.commitIndex + 1; idx <= lastIdx; idx++ {
		if n.log[idx].Term != n.currentTerm {
			continue // older entries commit indirectly, via a current-term entry
		}
		count := 1 // the leader stores its own entry
		for _, m := range n.matchIndex {
			if m >= idx {
				count++
			}
		}
		if count >= n.quorum() {
			n.commitIndex = idx
		}
	}
}
```

## The Paxos Acceptor and the Phase 1 Rule

Paxos decides one slot at a time. An acceptor promises not to honor older ballots and reports anything it has already accepted:

```go
// Acceptor holds single-decree Paxos state for one log slot.
type Acceptor struct {
	mu             sync.Mutex
	promised       uint64
	acceptedBallot uint64
	acceptedValue  *Entry
}

type Promise struct {
	OK             bool
	AcceptedBallot uint64
	AcceptedValue  *Entry
}

// Prepare is Phase 1b: promise to ignore lower ballots and report prior accepts.
func (a *Acceptor) Prepare(ballot uint64) Promise {
	a.mu.Lock()
	defer a.mu.Unlock()

	if ballot <= a.promised {
		return Promise{OK: false}
	}
	a.promised = ballot
	return Promise{OK: true, AcceptedBallot: a.acceptedBallot, AcceptedValue: a.acceptedValue}
}

// Accept is Phase 2b.
func (a *Acceptor) Accept(ballot uint64, v Entry) bool {
	a.mu.Lock()
	defer a.mu.Unlock()

	if ballot < a.promised {
		return false
	}
	a.promised = ballot
	a.acceptedBallot = ballot
	a.acceptedValue = &v
	return true
}

// chooseValue is the Phase 1 rule. Given promises from a quorum, a proposer
// must adopt the highest-ballot value already accepted. Only when no
// promise carries a value may it propose its own.
func chooseValue(promises []Promise, mine Entry) Entry {
	var best *Promise
	for i := range promises {
		p := &promises[i]
		if p.OK && p.AcceptedValue != nil &&
			(best == nil || p.AcceptedBallot > best.AcceptedBallot) {
			best = p
		}
	}
	if best != nil {
		return *best.AcceptedValue
	}
	return mine
}
```

## Zab's Discovery Step

Zab's new leader must adopt the most recent history among a quorum before it broadcasts anything. Zxids order transactions by epoch first, then by counter:

```go
type Zxid struct{ Epoch, Counter uint64 }

func (z Zxid) Less(o Zxid) bool {
	if z.Epoch != o.Epoch {
		return z.Epoch < o.Epoch
	}
	return z.Counter < o.Counter
}

// discover returns the responder with the most recent history. Callers must
// pass a quorum of responses; the new leader then synchronizes lagging
// nodes to that history before its first broadcast.
func discover(last map[string]Zxid) (string, Zxid) {
	var bestID string
	var best Zxid
	first := true
	for id, z := range last {
		if first || best.Less(z) {
			bestID, best, first = id, z, false
		}
	}
	return bestID, best
}
```

## How the Pieces Fit Together

Walking through a Kestrel debit shows where each protocol enforces safety.

**Raft.** The leader's `Propose` appends the debit to its log. `HandleAppendEntries` on each follower checks that the previous entry matches, which is the Log Matching guarantee, and only then stores the new entry and reports success. Once the leader's `advanceCommit` counts 3 nodes with the entry, it commits. Two checks prevent unsafe commits. `HandleRequestVote` refuses candidates with stale logs, so a winner always holds every committed entry. `advanceCommit` refuses to count old-term entries by themselves. Both checks are in the code above, not in prose.

**Paxos.** The same slot is decided by acceptors. A new proposer calls `Prepare` on a quorum and passes the responses to `chooseValue`. If slot 41 was already accepted by A, B, and C, any quorum of promises includes at least one of them, and the proposer is forced to re-propose the debit rather than something else. The rule is simple to state and easy to get wrong. The code makes it explicit.

**Zab.** `discover` selects the node whose history is most recent by zxid. Once that history is adopted and a quorum has synchronized to it, the leader begins broadcasting. The committed prefix is established before new work starts, which is why Zab does not need Raft's separate old-term commit rule.

## What This Sketch Does Not Cover

Several things a production system needs are missing: election timeouts and the candidate loop, the RPC transport, the leader's `matchIndex` updates after successful `AppendEntries` calls, log compaction, membership changes, and the state-machine apply loop that consumes `commitIndex`. The `Store` implementation must also fsync before returning, as covered in the failure-story section.

For real systems, use a tested library such as etcd's `raft` package or ZooKeeper itself, and verify any custom logic with fault injection and model checking. The code here is useful for reading those libraries, because the same checks appear in them under different names.

Key takeaway: The safety of all three protocols reduces to a few checks in code, namely the vote's log-freshness test, Raft's log-matching and current-term commit rule, Paxos's highest-ballot value adoption, and Zab's most-recent-history discovery, and each check is only as trustworthy as the durability of the state it reads.

# Core Concepts in CAP and Consistency Models

The overview introduced CAP and the consistency model hierarchy. This section goes deeper into the concepts that cause the most design errors for senior engineers: what linearizability requires, how availability is defined per request, why latency matters even when nothing is partitioned, how session guarantees work, why causal consistency is the strongest model that can remain available, and how eventually consistent systems converge. Each concept is illustrated with Kestrel, our payments ledger on 5 nodes across `us-east`, `eu-west`, and `ap-south`.

## 1. Linearizability Is a Statement About Real Time

Linearizability is often described as "strong consistency," but the definition is more specific. Each operation has an invocation time and a response time. The system is linearizable if every operation can be assigned a single point, called a linearization point, between its invocation and its response, such that the resulting sequence of points is a valid sequential history for the object.

Two properties make this definition demanding. The first is that the linearization point must fall within the operation's real-time window, so the order must respect when things actually happened. The second is that all observers must agree on that single order.

Consider Kestrel's balance for `acct-7`. A debit of 4000 cents completes at 10:00:00.120. A read that begins at 10:00:00.130 must return a balance reflecting the debit. A read that began at 10:00:00.100 and overlaps the debit may return either the old or the new balance, but once any client has observed the new balance, no later read may return the old one. That last rule is the one that stale followers violate, and it is the reason authorization checks need a path that a linearizable read can take. A linearizability checker tests exactly this by recording invocation and response times and searching for a valid linearization.

The practical point for senior engineers is that linearizability is a property of an object, not a transaction. For multi-key work, the corresponding model is strict serializability, which combines serializable transactions with real-time order. Confusing the two causes errors in transfer logic that spans accounts.

## 2. Availability Is Defined Per Request, Not Per Cluster

CAP's availability requirement is that every request received by a non-failing node receives a non-error response. This sounds like a restatement of uptime, but the unit is the individual request, and the question is which nodes are allowed to answer.

When Kestrel's `us-east` pair is partitioned from the other three nodes, a payment request routed to a `us-east` node cannot be committed, because that node cannot reach a majority. Under CAP's definition, that request is unavailable, even though the cluster as a whole is serving payments through the majority side. The distinction matters for capacity planning and customer communication. A regional partition is a partial outage for the customers routed to that region, not a minor event.

Two design responses exist. The first is to route clients to the majority side, which turns some unavailable requests into successful ones. The second is to decide, per operation, whether the minority side should answer at all. A balance inquiry on the minority side can return a stale value with an explicit staleness marker, which is available but not linearizable. A debit cannot. That per-operation decision is the actual CAP choice a senior engineer makes, and it should be documented in the API contract, not discovered during an incident.

## 3. PACELC: Latency Is the Cost You Pay Every Day

Partitions are rare. Latency is constant. The PACELC framing makes this explicit: if there is a partition, the system chooses between availability and consistency; else, it chooses between latency and consistency.

For Kestrel, the normal-case trade-off dominates the design. A linearizable write must be acknowledged by a majority, and with 2 nodes in `us-east`, 2 in `eu-west`, and 1 in `ap-south`, the write needs at least one cross-region acknowledgment. With an 80 ms round trip between `us-east` and `eu-west`, every confirmed payment pays roughly that latency. A linearizable read through the log pays the same. ReadIndex avoids the log entry but still requires a heartbeat round to a quorum, so it pays most of that cost too.

Leases remove that round trip, which is their attraction, but they require bounded clock drift, as the earlier clock-fault failure story showed. So the latency-consistency choice has a precise meaning for Kestrel: linearizable reads cost one cross-region round trip, and the only way to avoid it is to accept a dependency on clocks. Senior engineers should quantify this per operation, because a dashboard that refreshes every few seconds can take the lease path, while an authorization check on a payment should not.

## 4. Session Guarantees Make Weak Models Usable

Most user-facing systems do not need linearizability for every read. They need a client to see its own actions and not see time run backward. Session guarantees capture these needs, and they can be provided at low cost by tracking what each client has observed.

The four classic guarantees are:

- **Read-your-writes.** A client sees its own completed writes.
- **Monotonic reads.** A client's successive reads never go backward in time.
- **Monotonic writes.** A client's writes are applied in the order issued.
- **Writes-follow-reads.** A write is applied only after the data it was based on.

Kestrel's customer app illustrates the first two. After a payment confirms, the app must show it. After it shows a balance, a subsequent refresh must not show an older balance, even if the refresh hits a different node. The implementation is a session token that carries the highest commit index the client has seen, and nodes that have not reached that index refuse the read or redirect it. The token is small, travels with each response, and eliminates the most visible anomalies without making every read linearizable.

## 5. Causal Consistency Is the Strongest Model Compatible With Availability

Causal consistency requires that operations with a causal relationship be observed in the same order by all nodes. Operations with no causal relationship may be observed in different orders. Causality is the transitive closure of two rules: a process's operations are ordered, and a message receipt follows the send that caused it. This is the happens-before relation.

Causal consistency matters because, unlike linearizability, it can be provided without a majority during a partition. Each side of a partition can accept writes, provided each side preserves causal order internally and sessions stick to a consistent set of nodes. That makes it the strongest model compatible with availability under partitions, which is a result that is often overlooked.

Vector clocks are the standard mechanism for detecting causal relationships between writes made on different nodes:

```go
// VectorClock maps a node ID to the number of events observed from it.
type VectorClock map[string]uint64

// Compare returns -1 if a happened before b, 1 if b happened before a,
// 0 if they are equal, and 2 if they are concurrent.
func (a VectorClock) Compare(b VectorClock) int {
	aLess, bLess := false, false
	keys := make(map[string]struct{})
	for k := range a {
		keys[k] = struct{}{}
	}
	for k := range b {
		keys[k] = struct{}{}
	}
	for k := range keys {
		if a[k] < b[k] {
			aLess = true
		}
		if b[k] < a[k] {
			bLess = true
		}
	}
	switch {
	case aLess && bLess:
		return 2
	case aLess:
		return -1
	case bLess:
		return 1
	default:
		return 0
	}
}
```

For Kestrel, a refund that references a specific payment must not be applied on any node before that payment. Causal delivery guarantees this, while two unrelated debits on different accounts may be applied in either order. Concurrent writes, which return 2, are the ones that need a conflict-resolution rule, and for money the rule must reject one of them rather than merge them.

## 6. Eventual Consistency Requires an Explicit Convergence Rule

Eventual consistency guarantees only that, once writes stop, all nodes converge. Convergence is not automatic. Nodes that accept concurrent writes must agree on a resolution rule, and the choice of rule determines what data is lost.

Last-writer-wins is the simplest rule and the most dangerous for money. It keeps the write with the highest timestamp, which discards the other write silently. If Kestrel's `us-east` and `eu-west` nodes each accept a debit against the same account during a partition, last-writer-wins keeps one and drops the other, and the customer is charged once for two purchases.

Conflict-free replicated data types avoid silent loss by restricting operations to ones that commute. A grow-only counter is the simplest example, and it suits analytics well, because a sum of per-node counts is the same regardless of merge order:

```go
// GCounter is a grow-only counter. Each node increments only its own slot,
// and merging takes the per-node maximum, so merge order does not matter.
type GCounter map[string]uint64

func (c GCounter) Increment(nodeID string, delta uint64) {
	c[nodeID] += delta
}

func (c GCounter) Merge(other GCounter) {
	for id, v := range other {
		if v > c[id] {
			c[id] = v
		}
	}
}

func (c GCounter) Value() uint64 {
	var total uint64
	for _, v := range c {
		total += v
	}
	return total
}
```

A GCounter can count payments per region for a dashboard that converges after a partition heals. It cannot enforce a balance floor, because two nodes can each check the floor against stale state. That is the boundary for convergent types: they are excellent for aggregates that do not need invariants, and unsuitable for balances that must never go negative.

## Putting the Concepts Together

These six concepts form a single decision process. Start by stating the consistency model each operation requires, using linearizability for authorization and strict serializability for multi-account transfers. Define the availability behavior per operation during a partition, and quantify the latency cost of each model during normal operation. For weaker models, use session guarantees for user-facing views and causal ordering where the data has dependencies. Only use eventual consistency with a convergence rule that cannot silently discard a financial write.

A senior engineer who can answer these questions for each operation can explain a system's behavior under partition, under load, and under a regional outage, and can defend the choice to the people who will be paged when it fails.

Key takeaway: The CAP theorem constrains behavior only during partitions, while the consistency models let each operation choose the weakest guarantee it can safely accept, so Kestrel should pay for linearizability on money movement, use session guarantees and causal ordering for customer views, and apply convergent types only where no invariant depends on the merged value.

# A CAP and Consistency Simulator in Go

This section builds a small, deterministic simulator of Kestrel's 5-node cluster. It models network partitions as a reachability matrix, implements the three read levels and the write rule, adds a client that carries a session token, and includes an availability-first alternative that shows what happens when writes are accepted on both sides of a partition. The tests walk through the scenarios from the worked example.

The simulator is a teaching model. It has no real network, no elections, and no fsync. Its leader state stands in for ReadIndex, so the linearizable read path is simplified. The decisions it makes, though, are the ones a real Kestrel gateway has to make.

## The Cluster and Its Partitions

The package is named `consistency` to avoid confusion with Go's built-in `cap` function.

```go
package consistency

import (
	"errors"
	"sync"
)

// Level selects the consistency a read requires.
type Level int

const (
	Linearizable Level = iota // contacts a majority; sees every committed write
	Session                   // local node, but only if it has applied the client's token
	Local                     // local node, any state: available, possibly stale
)

var (
	ErrNoQuorum          = errors.New("no majority reachable from the leader")
	ErrStale             = errors.New("node has not applied the session index")
	ErrInsufficientFunds = errors.New("insufficient funds")
)

// Entry is one ledger operation. Index is assigned on commit.
type Entry struct {
	Index       uint64
	IdemKey     string
	Account     string
	AmountCents int64
}

// Node is one Kestrel node. It applies committed entries in log order.
type Node struct {
	ID       string
	Region   string
	applied  uint64
	balances map[string]int64
}

// Cluster simulates Kestrel's 5 nodes. reach[i][j] reports whether node i
// can deliver messages to node j. A partition clears entries across groups.
type Cluster struct {
	mu     sync.Mutex
	nodes  []*Node
	reach  [][]bool
	leader int
	log    []Entry // log[k] has Index k+1
	commit uint64
}

// NewCluster builds Kestrel's layout: 2 nodes in us-east, 2 in eu-west,
// 1 in ap-south. Node 2 (eu-west-1) starts as leader.
func NewCluster() *Cluster {
	layout := []struct{ id, region string }{
		{"us-east-1", "us-east"}, {"us-east-2", "us-east"},
		{"eu-west-1", "eu-west"}, {"eu-west-2", "eu-west"},
		{"ap-south-1", "ap-south"},
	}
	c := &Cluster{leader: 2}
	for _, s := range layout {
		c.nodes = append(c.nodes, &Node{
			ID: s.id, Region: s.region, balances: make(map[string]int64),
		})
	}
	c.reach = fullMesh(len(layout))
	return c
}

func fullMesh(n int) [][]bool {
	r := make([][]bool, n)
	for i := range r {
		r[i] = make([]bool, n)
		for j := range r[i] {
			r[i][j] = true
		}
	}
	return r
}

// Partition cuts every link between the two groups of node indexes.
func (c *Cluster) Partition(a, b []int) {
	c.mu.Lock()
	defer c.mu.Unlock()
	for _, i := range a {
		for _, j := range b {
			c.reach[i][j], c.reach[j][i] = false, false
		}
	}
}

// Heal restores full connectivity and lets every node catch up.
func (c *Cluster) Heal() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.reach = fullMesh(len(c.nodes))
	for i := range c.nodes {
		c.catchUp(i)
	}
}

func (c *Cluster) quorum() int { return len(c.nodes)/2 + 1 }

// reachableFromLeader counts nodes the leader can reach, including itself.
func (c *Cluster) reachableFromLeader() int {
	n := 0
	for j := range c.nodes {
		if c.reach[c.leader][j] {
			n++
		}
	}
	return n
}

// canCommit reports whether a request entering at node `from` can reach the
// leader and the leader can reach a majority. This is the CP write rule.
func (c *Cluster) canCommit(from int) bool {
	return c.reach[from][c.leader] && c.reachableFromLeader() >= c.quorum()
}

// catchUp applies committed entries that node i has not seen, but only if
// the leader can currently reach it.
func (c *Cluster) catchUp(i int) {
	if !c.reach[c.leader][i] {
		return
	}
	n := c.nodes[i]
	for n.applied < c.commit {
		e := c.log[n.applied]
		n.balances[e.Account] += e.AmountCents
		n.applied = e.Index
	}
}

// appendLocked commits an entry. Callers hold c.mu and have checked canCommit.
func (c *Cluster) appendLocked(e Entry) uint64 {
	e.Index = uint64(len(c.log) + 1)
	c.log = append(c.log, e)
	c.commit = e.Index
	for i := range c.nodes {
		c.catchUp(i)
	}
	return e.Index
}

func (c *Cluster) findKey(key string) (uint64, bool) {
	for _, e := range c.log {
		if e.IdemKey == key {
			return e.Index, true
		}
	}
	return 0, false
}
```

## Writes: The CP Rule

```go
// Credit adds funds as an ordinary committed entry. It is used for setup.
func (c *Cluster) Credit(acct string, cents int64, key string) (uint64, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if !c.canCommit(c.leader) {
		return 0, ErrNoQuorum
	}
	if idx, ok := c.findKey(key); ok {
		return idx, nil
	}
	return c.appendLocked(Entry{IdemKey: key, Account: acct, AmountCents: cents}), nil
}

// Debit is the CP write path. It refuses unless the request can reach a
// majority, checks the balance against committed state, and deduplicates
// by idempotency key so client retries are safe.
func (c *Cluster) Debit(from int, acct string, cents int64, key string) (uint64, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if !c.canCommit(from) {
		return 0, ErrNoQuorum
	}
	if idx, ok := c.findKey(key); ok {
		return idx, nil
	}
	if c.nodes[c.leader].balances[acct] < cents {
		return 0, ErrInsufficientFunds
	}
	return c.appendLocked(Entry{IdemKey: key, Account: acct, AmountCents: -cents}), nil
}
```

## Reads: Three Levels

```go
// Read serves a balance at the requested level. token is the client's
// minimum applied index and matters only for Session reads. It returns the
// balance, the index the answer reflects, and any error.
func (c *Cluster) Read(from int, level Level, acct string, token uint64) (int64, uint64, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	switch level {
	case Linearizable:
		// A real gateway uses ReadIndex here: confirm leadership with a
		// heartbeat round, then serve. This model checks reachability directly.
		if !c.canCommit(from) {
			return 0, 0, ErrNoQuorum
		}
		return c.nodes[c.leader].balances[acct], c.commit, nil
	case Session:
		n := c.nodes[from]
		if n.applied < token {
			return 0, n.applied, ErrStale
		}
		return n.balances[acct], n.applied, nil
	default: // Local
		n := c.nodes[from]
		return n.balances[acct], n.applied, nil
	}
}

// Client carries a session token: the highest commit index it has observed.
type Client struct {
	token uint64
}

// Observe records an index the client learned from a completed write or read.
func (cl *Client) Observe(index uint64) {
	if index > cl.token {
		cl.token = index
	}
}

// ReadSession reads through node `from` and enforces read-your-writes.
func (cl *Client) ReadSession(c *Cluster, from int, acct string) (int64, error) {
	bal, applied, err := c.Read(from, Session, acct, cl.token)
	if err != nil {
		return 0, err
	}
	cl.Observe(applied)
	return bal, nil
}
```

## The Availability-First Alternative

```go
// APSide is one side of a partition in an availability-first design. Each
// side accepts debits against its own view and reconciles after healing.
type APSide struct {
	Balance  int64
	Accepted []int64
}

func (s *APSide) Debit(cents int64) error {
	if s.Balance < cents {
		return ErrInsufficientFunds
	}
	s.Balance -= cents
	s.Accepted = append(s.Accepted, cents)
	return nil
}

// Reconcile merges two sides that began from the same balance. The correct
// result subtracts every accepted debit from the starting balance, and the
// result shows that no single side ever overdrew while the total did.
func Reconcile(start int64, a, b *APSide) (final int64, overdrawn bool) {
	var total int64
	for _, d := range a.Accepted {
		total += d
	}
	for _, d := range b.Accepted {
		total += d
	}
	final = start - total
	return final, final < 0
}
```

