package consistency

import "testing"

// The minority side of a partition refuses writes, and the refusal leaves
// no trace in the ledger.
func TestMinorityRefusesWrite(t *testing.T) {
	c := NewCluster()
	c.Credit("acct-7", 10000, "seed")
	c.Partition([]int{0, 1}, []int{2, 3, 4}) // us-east cut off

	if _, err := c.Debit(0, "acct-7", 4000, "pay-1"); err != ErrNoQuorum {
		t.Fatalf("minority debit: got %v, want ErrNoQuorum", err)
	}
	c.Heal()
	bal, _, err := c.Read(0, Linearizable, "acct-7", 0)
	if err != nil || bal != 10000 {
		t.Fatalf("after heal: balance %d err %v, want 10000", bal, err)
	}
}

// The majority side keeps accepting writes during the partition.
func TestMajorityStaysAvailable(t *testing.T) {
	c := NewCluster()
	c.Credit("acct-7", 10000, "seed")
	c.Partition([]int{0, 1}, []int{2, 3, 4})

	if _, err := c.Debit(2, "acct-7", 4000, "pay-1"); err != nil {
		t.Fatalf("majority debit failed: %v", err)
	}
}

// A client that observed a write must not be served a stale node's
// earlier state. Local reads expose the staleness, Session reads refuse it,
// and healing makes the session read succeed with the new balance.
func TestSessionReadRefusesStale(t *testing.T) {
	c := NewCluster()
	c.Credit("acct-7", 10000, "seed")
	c.Partition([]int{0, 1}, []int{2, 3, 4})

	idx, err := c.Debit(2, "acct-7", 4000, "pay-1")
	if err != nil {
		t.Fatalf("debit: %v", err)
	}
	cl := &Client{}
	cl.Observe(idx)

	if _, err := cl.ReadSession(c, 0, "acct-7"); err != ErrStale {
		t.Fatalf("session read on stale node: got %v, want ErrStale", err)
	}
	bal, applied, _ := c.Read(0, Local, "acct-7", 0)
	if bal != 10000 || applied != 1 {
		t.Fatalf("local read: balance %d applied %d, want 10000 at index 1", bal, applied)
	}

	c.Heal()
	bal, err = cl.ReadSession(c, 0, "acct-7")
	if err != nil || bal != 6000 {
		t.Fatalf("session read after heal: balance %d err %v, want 6000", bal, err)
	}
}

// Each side of an availability-first partition accepts a debit that is
// affordable locally, and the merged result is overdrawn.
func TestAPReconcileOverdraws(t *testing.T) {
	us := &APSide{Balance: 10000}
	eu := &APSide{Balance: 10000}

	if err := us.Debit(6000); err != nil {
		t.Fatalf("us-east side refused: %v", err)
	}
	if err := eu.Debit(5000); err != nil {
		t.Fatalf("eu-west side refused: %v", err)
	}
	final, overdrawn := Reconcile(10000, us, eu)
	if final != -1000 || !overdrawn {
		t.Fatalf("reconcile: final %d overdrawn %v, want -1000 true", final, overdrawn)
	}
}
