func TestCommittedWritesSurviveFailover(t *testing.T) {
	c := kestrel(nil, 0)
	c.Append("acct-7", 10000)
	c.Append("acct-7", -4000)

	if err := c.Failover(3); err != nil {
		t.Fatalf("failover: %v", err)
	}
	if got := c.nodes[3].balances["acct-7"]; got != 6000 {
		t.Fatalf("balance after failover: got %d, want 6000", got)
	}
	if _, err := c.Append("acct-7", -1000); err != nil {
		t.Fatalf("append on new leader: %v", err)
	}
