func TestLaggingCandidateRefused(t *testing.T) {
	c := kestrel(nil, 0)
	c.nodes[1].up = false
	c.Append("acct-7", 10000)
	c.Append("acct-7", -4000)

	if err := c.Failover(1); err != ErrStaleCandidate {
		t.Fatalf("failover to lagging node: got %v, want ErrStaleCandidate", err)
	}
}

// The former leader's storage refuses its writes once the new epoch is fenced,
// so a process that still believes it leads cannot change the ledger.
func TestOldLeaderFencedAtStorage(t *testing.T) {
	c := kestrel(nil, 0)
	c.Append("acct-7", 10000)
	if err := c.Failover(3); err != nil {
		t.Fatalf("failover: %v", err)
	}
	stale := Entry{Index: 2, Epoch: 1, Account: "acct-7", Cents: -500}
	if err := c.nodes[2].Accept(stale); err != ErrFenced {
		t.Fatalf("old leader write: got %v, want ErrFenced", err)
	}
}

// The async gate caps how far a consumer may fall behind. Writes stop at the
// bound, and recover once the consumer catches up.
func TestAsyncGateBoundsLoss(t *testing.T) {
	c := kestrel([]int{4}, 2)
	c.nodes[4].up = false

	accepted := 0
	for i := 0; i < 10; i++ {
		if _, err := c.Append("acct-7", 100); err != nil {
			if err != ErrLagExceeded {
				t.Fatalf("unexpected error: %v", err)
			}
			break
		}
		accepted++
	}
	if accepted != 3 {
		t.Fatalf("accepted %d writes before gating, want 3", accepted)
	}

	c.nodes[4].up = true
	c.Ship(10)
	if lag := c.Lag(4); lag != 0 {
		t.Fatalf("lag after ship: %d, want 0", lag)
	}
	if _, err := c.Append("acct-7", 100); err != nil {
		t.Fatalf("append after recovery: %v", err)
	}
