// that write. Each iteration rebuilds stale nodes, so read repair in one case
// cannot hide a failure in another.
func TestEveryReaderSetSeesAcknowledgedWrite(t *testing.T) {
	for a := 0; a < 5; a++ {
		for b := a + 1; b < 5; b++ {
			for c := b + 1; c < 5; c++ {
				nodes := newKVNodes(5)
				s, err := NewQuorumStore(nodes, 3, 3, true, false)
				if err != nil {
					t.Fatalf("config: %v", err)
				}
				s.Put("acct-7", 10000, 1)
				nodes[3].Up, nodes[4].Up = false, false
				s.Put("acct-7", 6000, 2) // acknowledged by nodes 0, 1, 2
				nodes[3].Up, nodes[4].Up = true, true

				got, err := s.Get("acct-7", []int{a, b, c})
				if err != nil || got.Version != 2 {
