}

// Edits made in two regions without seeing each other are kept as siblings.
// A later edit that has seen both resolves the conflict.
func TestConcurrentContactEditsAreKeptAsSiblings(t *testing.T) {
	apEdit := Contact{Value: "12 Harbour Rd", Clock: Clock{"ap-south": 2}}
	euEdit := Contact{Value: "9 Quay St", Clock: Clock{"ap-south": 1, "eu-west": 1}}

	conflict := Reconcile(apEdit, euEdit)
	if len(conflict.Siblings) != 2 {
		t.Fatalf("siblings: got %v, want both edits", conflict.Siblings)
	}

	resolved := Contact{Value: "12 Harbour Rd", Clock: Clock{"ap-south": 3, "eu-west": 1}}
	if r := Reconcile(conflict, resolved); r.Siblings != nil || r.Value != resolved.Value {
		t.Fatalf("resolved edit: got %+v, want the resolution", r)
	}
}
