The example is a single-file Go program with no dependencies. It contains a two-phase commit coordinator with a fenced decision log, partitions that hold locks and check terms, and a saga runner with classified steps, persisted progress, and compensation. It runs the scenarios from the worked example.

```go
package main

import (
	"errors"
	"fmt"
	"sync"
)

var (
	ErrUnavailable  = errors.New("unavailable")
	ErrLocked       = errors.New("locked by another transaction")
	ErrRejected     = errors.New("rejected: inbound hold")
	ErrInsufficient = errors.New("insufficient funds")
	ErrStaleTerm    = errors.New("stale term")
	ErrConflict     = errors.New("conflicting outcome")
	ErrNotPrepared  = errors.New("not prepared")
	ErrAborted      = errors.New("transaction aborted")
	ErrRolledBack   = errors.New("saga rolled back")
	errCrashed      = errors.New("coordinator crashed (simulated)")
)

// ---------- Partition: participant for 2PC and saga steps ----------

// leg is one account's share of a transfer, applied on one partition.
type leg struct {
	p     *Partition
	acct  string
	delta int64
}

// Partition holds balances, locks, prepared state, and idempotency records.
// Every mutation is guarded by mu, standing in for a consensus-backed log.
type Partition struct {
	mu          sync.Mutex
	balances    map[string]int64
	locks       map[string]string // account -> txn holding it
	prepared    map[string]leg    // txn -> pending leg
	terms       map[string]uint64 // txn -> highest coordinator term accepted
	outcomes    map[string]bool   // txn -> decided (true = commit)
	applied     map[string]bool   // saga step key -> applied
	inboundHold map[string]bool   // account refusing credits
}

func NewPartition(balances map[string]int64) *Partition {
	return &Partition{
		balances:    balances,
		locks:       map[string]string{},
		prepared:    map[string]leg{},
		terms:       map[string]uint64{},
		outcomes:    map[string]bool{},
		applied:     map[string]bool{},
		inboundHold: map[string]bool{},
	}
}

func (p *Partition) Balance(acct string) int64 {
	p.mu.Lock()
	defer p.mu.Unlock()
	return p.balances[acct]
}

func (p *Partition) HoldInbound(acct string) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.inboundHold[acct] = true
}

// Prepare is the 2PC vote. A YES promises the decision will be honored, so the
// leg stays locked until Decide arrives.
func (p *Partition) Prepare(txn string, term uint64, l leg) (bool, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if term < p.terms[txn] {
		return false, ErrStaleTerm
	}
	p.terms[txn] = term
	if commit, decided := p.outcomes[txn]; decided {
		return commit, nil
	}
	if _, ok := p.prepared[txn]; ok {
		return true, nil // prepare is idempotent
	}
	if _, locked := p.locks[l.acct]; locked {
		return false, nil
	}
	if l.delta > 0 && p.inboundHold[l.acct] {
		return false, nil
	}
	if p.balances[l.acct]+l.delta < 0 {
		return false, nil
	}
	p.locks[l.acct] = txn
	p.prepared[txn] = l
	return true, nil
}

// Decide applies the coordinator's outcome. Stale terms are refused, and a
// repeated decision returns success without applying the effect again.
func (p *Partition) Decide(txn string, term uint64, commit bool) error {
	p.mu.Lock()
	defer p.mu.Unlock()
	if term < p.terms[txn] {
		return ErrStaleTerm
	}
	p.terms[txn] = term
	if prev, decided := p.outcomes[txn]; decided {
		if prev != commit {
			return ErrConflict
		}
		return nil
	}
	l, prepared := p.prepared[txn]
	if commit && !prepared {
		return ErrNotPrepared
	}
	if prepared {
		if commit {
			p.balances[l.acct] += l.delta
		}
		delete(p.locks, l.acct)
		delete(p.prepared, txn)
	}
	p.outcomes[txn] = commit
	return nil
}

// ApplyStep is a saga step: a single local commit, keyed for idempotency.
// Unlike 2PC it does not wait for a decision, so it refuses locked accounts
// with a transient error and lets the saga retry.
func (p *Partition) ApplyStep(key, acct string, delta int64) error {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.applied[key] {
		return nil
	}
	if _, locked := p.locks[acct]; locked {
		return ErrLocked
	}
	if delta > 0 && p.inboundHold[acct] {
		return ErrRejected
	}
	if p.balances[acct]+delta < 0 {
		return ErrInsufficient
	}
	p.balances[acct] += delta
	p.applied[key] = true
	return nil
}

// ---------- Decision log: the coordinator's durable state ----------

type State int

const (
	Preparing State = iota
	Committed
	Aborted
)

type Entry struct {
	Txn, From, To string
	Cents         int64
	Term          uint64
	State         State
}

// DecisionLog stands in for the coordinator's consensus-backed log. It refuses
// writes from lower terms and any change to a terminal outcome.
type DecisionLog struct {
	mu      sync.Mutex
	entries map[string]Entry
}

func NewDecisionLog() *DecisionLog {
	return &DecisionLog{entries: map[string]Entry{}}
}

func (l *DecisionLog) Put(e Entry) error {
	l.mu.Lock()
	defer l.mu.Unlock()
	if cur, ok := l.entries[e.Txn]; ok {
		if e.Term < cur.Term {
			return ErrStaleTerm
		}
		if cur.State != Preparing && e.State != cur.State {
			return ErrConflict
		}
	}
	l.entries[e.Txn] = e
	return nil
}

func (l *DecisionLog) Get(txn string) (Entry, bool) {
	l.mu.Lock()
	defer l.mu.Unlock()
	e, ok := l.entries[txn]
	return e, ok
}

func (l *DecisionLog) All() []Entry {
	l.mu.Lock()
	defer l.mu.Unlock()
	out := make([]Entry, 0, len(l.entries))
	for _, e := range l.entries {
		out = append(out, e)
	}
	return out
}

// ---------- Two-phase commit coordinator ----------

type Coordinator struct {
	term          uint64
	decisions     *DecisionLog
	route         map[string]*Partition
	afterDecision func(txn string) error // test hook: simulate a crash
}

func NewCoordinator(term uint64, decisions *DecisionLog, route map[string]*Partition) *Coordinator {
	return &Coordinator{term: term, decisions: decisions, route: route}
}

func (c *Coordinator) legs(e Entry) []leg {
	return []leg{
		{p: c.route[e.From], acct: e.From, delta: -e.Cents},
		{p: c.route[e.To], acct: e.To, delta: e.Cents},
	}
}

// Transfer runs prepare, makes the decision durable, then delivers it.
// The decision write is the commit point.
func (c *Coordinator) Transfer(txn, from, to string, cents int64) error {
	if cur, ok := c.decisions.Get(txn); ok {
		switch cur.State {
		case Committed:
			return nil
		case Aborted:
			return ErrAborted
		default:
			return fmt.Errorf("transaction %s in flight under term %d", txn, cur.Term)
		}
	}
	e := Entry{Txn: txn, From: from, To: to, Cents: cents, Term: c.term, State: Preparing}
	if err := c.decisions.Put(e); err != nil {
		return err
	}

	commit := true
	for _, l := range c.legs(e) {
		yes, err := l.p.Prepare(txn, c.term, l)
		if err != nil || !yes {
			commit = false
			break
		}
	}

	if commit {
		e.State = Committed
	} else {
		e.State = Aborted
	}
	if err := c.decisions.Put(e); err != nil {
		return err // undecided: participants stay locked until recovery
	}
	if c.afterDecision != nil {
		if err := c.afterDecision(txn); err != nil {
			return err
		}
	}

	// The outcome is durable, so a delivery failure is repaired by Recover.
	_ = c.deliver(e)
	if e.State == Aborted {
		return ErrAborted
	}
	return nil
}

func (c *Coordinator) deliver(e Entry) error {
	commit := e.State == Committed
	var firstErr error
	for _, l := range c.legs(e) {
		if err := l.p.Decide(e.Txn, c.term, commit); err != nil && firstErr == nil {
			firstErr = err
		}
	}
	return firstErr
}

// Recover runs on a new leader in a higher term. A recorded outcome is
// re-sent under the new term. A transaction still Preparing is presumed
// aborted. Because the log fences lower terms, a stale leader can no longer
// record a different outcome for the same transaction.
func (c *Coordinator) Recover() error {
	var firstErr error
	for _, e := range c.decisions.All() {
		if e.State == Preparing {
			e.State = Aborted
		}
		e.Term = c.term
		if err := c.decisions.Put(e); err != nil {
			return err
		}
		if err := c.deliver(e); err != nil && firstErr == nil {
			firstErr = err
		}
	}
	return firstErr
}

// ---------- Saga runner ----------

type StepKind int

const (
	Compensable StepKind = iota // can be undone; runs before the pivot
	Pivot                       // the point of no return; exactly one per saga
	Retriable                   // runs after the pivot; retried until it succeeds
)

type Step struct {
	Name string
	Kind StepKind
	Do   func(key string) error
	Undo func(key string) error // required for Compensable steps
}

type sagaRecord struct {
	Completed    []string
	Undone       []string
	Compensating bool
	RolledBack   bool
	Finished     bool
}

// SagaLog stands in for durable saga progress, so a runner can resume.
type SagaLog struct {
	records map[string]*sagaRecord
}

func NewSagaLog() *SagaLog {
	return &SagaLog{records: map[string]*sagaRecord{}}
}

func (l *SagaLog) get(id string) *sagaRecord {
	r, ok := l.records[id]
	if !ok {
		r = &sagaRecord{}
		l.records[id] = r
	}
	return r
}

type Saga struct {
	id         string
	sagas      *SagaLog
	steps      []Step
	maxRetries int
}

func NewSaga(id string, sagas *SagaLog, steps []Step, maxRetries int) (*Saga, error) {
	if err := validate(steps); err != nil {
		return nil, err
	}
	return &Saga{id: id, sagas: sagas, steps: steps, maxRetries: maxRetries}, nil
}

// validate enforces the ordering rule: compensable steps, then one pivot,
// then retriable steps only.
func validate(steps []Step) error {
	pivots := 0
	for _, s := range steps {
		switch {
		case pivots == 0 && s.Kind == Compensable:
			if s.Undo == nil {
				return fmt.Errorf("step %s: compensable steps need Undo", s.Name)
			}
		case s.Kind == Pivot:
			pivots++
		case pivots > 0 && s.Kind == Retriable:
		default:
			return fmt.Errorf("step %s: kind %d not allowed at this position", s.Name, s.Kind)
		}
	}
	if pivots != 1 {
		return errors.New("saga needs exactly one pivot step")
	}
	return nil
}

// Run can be called again after a failure. It resumes from recorded progress
// and never repeats a completed step.
func (s *Saga) Run() error {
	rec := s.sagas.get(s.id)
	switch {
	case rec.Finished:
		return nil
	case rec.RolledBack:
		return fmt.Errorf("saga %s: %w", s.id, ErrRolledBack)
	case rec.Compensating:
		return s.finishRollback(rec, nil)
	}

	for _, step := range s.steps {
		if contains(rec.Completed, step.Name) {
			continue
		}
		err := s.attempt(step, s.id+"/"+step.Name)
		if err == nil {
			rec.Completed = append(rec.Completed, step.Name)
			continue
		}
		if step.Kind == Retriable {
			return fmt.Errorf("saga %s: step %s pending: %w", s.id, step.Name, err)
		}
		// A failure before or at the pivot means the saga must roll back.
		rec.Compensating = true
		return s.finishRollback(rec, err)
	}
	rec.Finished = true
	return nil
}

// attempt retries only transient errors. A permanent error, such as an
// inbound hold, fails immediately. Production code would add backoff.
func (s *Saga) attempt(step Step, key string) error {
	var err error
	for i := 0; i < s.maxRetries; i++ {
		if err = step.Do(key); err == nil || !transient(err) {
			return err
		}
	}
	return err
}

func transient(err error) bool {
	return errors.Is(err, ErrLocked) || errors.Is(err, ErrUnavailable)
}

func (s *Saga) finishRollback(rec *sagaRecord, cause error) error {
	if err := s.rollback(rec); err != nil {
		return fmt.Errorf("saga %s: rollback pending: %w", s.id, err)
	}
	if cause == nil {
		return fmt.Errorf("saga %s: %w", s.id, ErrRolledBack)
	}
	return fmt.Errorf("saga %s: %w (cause: %v)", s.id, ErrRolledBack, cause)
}

// rollback undoes completed compensable steps in reverse order. Each undo
// uses its own key, so a repeated undo is harmless.
func (s *Saga) rollback(rec *sagaRecord) error {
	for i := len(rec.Completed) - 1; i >= 0; i-- {
		name := rec.Completed[i]
		if contains(rec.Undone, name) {
			continue
		}
		step := s.stepByName(name)
		if step.Kind != Compensable {
			continue
		}
		if err := step.Undo(s.id + "/" + name + "/comp"); err != nil {
			return fmt.Errorf("undo %s: %w", name, err)
		}
		rec.Undone = append(rec.Undone, name)
	}
	rec.Compensating = false
	rec.RolledBack = true
	return nil
}

func (s *Saga) stepByName(name string) Step {
	for _, st := range s.steps {
		if st.Name == name {
			return st
		}
	}
	panic("unknown step " + name)
}

func contains(xs []string, s string) bool {
	for _, x := range xs {
		if x == s {
			return true
		}
	}
	return false
}

// Notifier fails a set number of times, then succeeds. Sends are keyed, so a
// duplicate send is suppressed.
type Notifier struct {
	failures int
	sent     map[string]bool
}

func (n *Notifier) Send(key string) error {
	if n.sent[key] {
		return nil
	}
	if n.failures > 0 {
		n.failures--
		return ErrUnavailable
	}
	n.sent[key] = true
	return nil
}

func transferSteps(route map[string]*Partition, from, to string, cents int64, notify func(string) error) []Step {
	return []Step{
		{
			Name: "debit", Kind: Compensable,
			Do:   func(key string) error { return route[from].ApplyStep(key, from, -cents) },
			Undo: func(key string) error { return route[from].ApplyStep(key, from, cents) },
		},
		{
			Name: "credit", Kind: Pivot,
			Do: func(key string) error { return route[to].ApplyStep(key, to, cents) },
		},
		{
			Name: "notify", Kind: Retriable,
			Do: func(key string) error { return notify(key) },
		},
	}
}

// ---------- Demo ----------

func world() map[string]*Partition {
	p1 := NewPartition(map[string]int64{"merchant-17": 50000})
	p2 := NewPartition(map[string]int64{"merchant-42": 12000})
	return map[string]*Partition{"merchant-17": p1, "merchant-42": p2}
}

func show(label string, route map[string]*Partition) {
	fmt.Printf("  %-18s merchant-17=%d merchant-42=%d\n", label,
		route["merchant-17"].Balance("merchant-17"),
		route["merchant-42"].Balance("merchant-42"))
}

func main() {
	fmt.Println("== 2PC: normal commit")
	route := world()
	coord := NewCoordinator(7, NewDecisionLog(), route)
	err := coord.Transfer("tx-9981", "merchant-17", "merchant-42", 2000)
	fmt.Println("  result:", err)
	show("after commit", route)

	fmt.Println("== 2PC: coordinator crash after commit is logged")
	route = world()
	decisions := NewDecisionLog()
	old := NewCoordinator(7, decisions, route)
	old.afterDecision = func(string) error { return errCrashed }
	err = old.Transfer("tx-9981", "merchant-17", "merchant-42", 2000)
	fmt.Println("  transfer result:", err)
	show("before takeover", route)
	next := NewCoordinator(8, decisions, route)
	if err := next.Recover(); err != nil {
		fmt.Println("  recover error:", err)
	}
	show("after takeover", route)
	err = old.deliver(Entry{Txn: "tx-9981", From: "merchant-17", To: "merchant-42", State: Aborted})
	fmt.Println("  stale term-7 abort:", err)

	fmt.Println("== Saga: notification retried, transfer completes")
	route = world()
	notifier := &Notifier{failures: 2, sent: map[string]bool{}}
	saga, err := NewSaga("tx-9982", NewSagaLog(),
		transferSteps(route, "merchant-17", "merchant-42", 2000, notifier.Send), 3)
	if err != nil {
		panic(err)
	}
	err = saga.Run()
	fmt.Println("  result:", err)
	show("after saga", route)
	fmt.Println("  notifications sent:", len(notifier.sent))

	fmt.Println("== Saga: pivot rejected, debit compensated")
	route = world()
	route["merchant-42"].HoldInbound("merchant-42")
	notifier = &Notifier{sent: map[string]bool{}}
	saga, err = NewSaga("tx-9983", NewSagaLog(),
		transferSteps(route, "merchant-17", "merchant-42", 2000, notifier.Send), 3)
	if err != nil {
		panic(err)
	}
	err = saga.Run()
	fmt.Println("  result:", err)
	show("after rollback", route)
	fmt.Println("  notifications sent:", len(notifier.sent))
}
```

