The balances follow from the events. `merchant-17` starts at 50,000, loses 2,000 and 1,500, and ends at 46,500 with a hold of 500 still in place. `merchant-42` starts at 11,000, gains 1,000 from the legacy event, and receives 2,000 and 1,500, ending at 15,500. The global log has eight events, and the statement lines skip the hold because it does not change the balance.

Key takeaway: The example shows event sourcing as a set of invariants that each piece enforces: the store refuses writes against a stale version, the aggregate refuses overdrafts before any fact is recorded, commands resume safely after partial failure, projections commit state and position together, reads wait for the position they need, and cutover waits for verification against an independent computation. Each invariant is small in the code, but together they are what keep a ledger correct as the log grows, the schema changes, and the views are rebuilt.

# Reference Architecture in Code: A Single-Process Model

This example models the reference architecture's main mechanisms in one Go file, using only the standard library. It covers identity and policy, trace propagation, two-phase transfers across two shards, a durable decision log, term fencing, a coordinator failover, a projection with a minimum-position read, a verification gate, and a deadline check. The shards stand in for consensus groups over Kestrel's 5 nodes, and their majority commits are represented by synchronous calls. Nothing is persisted or sent over a network.

I have not compiled or run this file. The expected output at the end was derived by hand from the code.

```go
package main

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"
)

// Kestrel: 5 nodes across us-east (2), eu-west (2), ap-south (1); majority of 3.
// Each shard below stands in for a consensus group over those nodes. Its majority
// commit is a synchronous call here. Nothing is persisted or networked.

const (
	idPayments    = "spiffe://kestrel/ns/payments/sa/api"
	idCoordinator = "spiffe://kestrel/ns/payments/sa/coordinator"
	idReporting   = "spiffe://kestrel/ns/reporting/sa/exporter"

	userDeadline = 800 * time.Millisecond
	minAttempt   = 50 * time.Millisecond
)

var (
	ErrStaleTerm    = errors.New("stale term: a newer authority has already acted")
	ErrUnavailable  = errors.New("no majority reachable")
	ErrInsufficient = errors.New("insufficient available funds")
	ErrPending      = errors.New("decided but not yet delivered to every shard")
	ErrDeadline     = errors.New("remaining deadline too short for an attempt")
	ErrNotCaughtUp  = errors.New("projection has not reached the requested position")
	ErrGap          = errors.New("event position skips ahead of checkpoint")
	ErrDenied       = errors.New("caller not authorized for operation")
)

type Term uint64
type TxID string

// ---------- Identity and policy ----------

// Policy is default-deny: a caller may perform only the operations listed for it.
type Policy map[string]map[string]bool

func (p Policy) Authorize(caller, op string) error {
	if p[caller][op] {
		return nil
	}
	return fmt.Errorf("%s may not %s: %w", caller, op, ErrDenied)
}

// ---------- Tracing ----------

// SpanCtx is the propagated part of a span, using W3C trace and span identifiers.
type SpanCtx struct {
	Trace string
	Span  string
}

func (sc SpanCtx) Traceparent() string {
	if sc.Trace == "" {
		return ""
	}
	return "00-" + sc.Trace + "-" + sc.Span + "-01"
}

func ParseTraceparent(h string) (SpanCtx, error) {
	p := strings.Split(h, "-")
	if len(p) != 4 || p[0] != "00" || len(p[1]) != 32 || len(p[2]) != 16 {
		return SpanCtx{}, errors.New("malformed traceparent")
	}
	return SpanCtx{Trace: p[1], Span: p[2]}, nil
}

type Span struct {
	tracer  *Tracer
	Name    string
	Ctx     SpanCtx
	Parent  SpanCtx
	Links   []SpanCtx
	Attrs   map[string]string
	Events  []string
	outcome string
}

func (s *Span) Attr(k, v string) { s.Attrs[k] = v }
func (s *Span) Event(msg string) { s.Events = append(s.Events, msg) }
func (s *Span) Outcome(o string) { s.outcome = o }
func (s *Span) Result() string   { return s.outcome }
func (s *Span) End()             { s.tracer.finished = append(s.tracer.finished, s) }

type Tracer struct {
	seq      int
	finished []*Span
}

// Start opens a span. A zero parent starts a new trace. Links record related work
// that is not a child, such as a recovery of an earlier transfer.
func (t *Tracer) Start(name string, parent SpanCtx, links ...SpanCtx) *Span {
	t.seq++
	ctx := SpanCtx{Trace: parent.Trace, Span: fmt.Sprintf("%016x", t.seq)}
	if ctx.Trace == "" {
		ctx.Trace = fmt.Sprintf("%032x", t.seq)
	}
	return &Span{tracer: t, Name: name, Ctx: ctx, Parent: parent, Links: links,
		Attrs: map[string]string{}, outcome: "unset"}
}

func findSpan(t *Tracer, name string) *Span {
	for _, s := range t.finished {
		if s.Name == name {
			return s
		}
	}
	return nil
}

// ---------- Shards: the authority for balances ----------

// Event is an immutable fact committed by a shard. Pos is dense within the shard.
type Event struct {
	Pos   int64
	Acct  string
	Delta int64
	Tx    TxID
}

type leg struct {
	acct  string
	delta int64
}

// Shard decides balances for the accounts it owns. Every method that changes
// state checks the caller's term first, so a superseded coordinator is refused.
type Shard struct {
	name        string
	mu          sync.Mutex
	term        Term
	balances    map[string]int64
	prepared    map[TxID]leg
	outcomes    map[TxID]bool
	log         []Event
	partitioned bool
}

// NewShard records opening balances as events, so that a replay of the log
// reproduces every balance, including the opening ones.
func NewShard(name string, opening map[string]int64) *Shard {
	s := &Shard{name: name, balances: map[string]int64{}, prepared: map[TxID]leg{}, outcomes: map[TxID]bool{}}
	accts := make([]string, 0, len(opening))
	for a := range opening {
		accts = append(accts, a)
	}
	sort.Strings(accts)
	for _, a := range accts {
		s.balances[a] = opening[a]
		s.log = append(s.log, Event{Pos: int64(len(s.log)) + 1, Acct: a, Delta: opening[a], Tx: "open"})
	}
	return s
}

// observe moves the shard's term forward. A lower term is refused, because that
// authority has been superseded and its messages must not change anything.
func (s *Shard) observe(term Term) error {
	if term < s.term {
		return fmt.Errorf("%s has seen term %d, got %d: %w", s.name, s.term, term, ErrStaleTerm)
	}
	s.term = term
	return nil
}

// available is the balance less the debits held by prepared legs.
func (s *Shard) available(acct string) int64 {
	avail := s.balances[acct]
	for _, l := range s.prepared {
		if l.acct == acct && l.delta < 0 {
			avail += l.delta
		}
	}
	return avail
}

func (s *Shard) Prepare(tx TxID, term Term, acct string, delta int64) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.partitioned {
		return fmt.Errorf("%s: %w", s.name, ErrUnavailable)
	}
	if err := s.observe(term); err != nil {
		return err
	}
	if _, decided := s.outcomes[tx]; decided {
		return nil // a repeat of a prepare whose outcome is already recorded
	}
	if _, held := s.prepared[tx]; held {
		return nil // a repeat of a prepare already in progress
	}
	if delta < 0 && s.available(acct)+delta < 0 {
		return fmt.Errorf("%s %s: %w", s.name, acct, ErrInsufficient)
	}
	s.prepared[tx] = leg{acct, delta}
	return nil
}

func (s *Shard) Decide(tx TxID, term Term, commit bool) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.partitioned {
		return fmt.Errorf("%s: %w", s.name, ErrUnavailable)
	}
	if err := s.observe(term); err != nil {
		return err
	}
	if prior, decided := s.outcomes[tx]; decided {
		if prior != commit {
			return fmt.Errorf("%s %s: conflicting decision", s.name, tx)
		}
		return nil // the same decision applied twice is a no-op
	}
	l, held := s.prepared[tx]
	if !held {
		if commit {
			return fmt.Errorf("%s %s: commit without prepare", s.name, tx)
		}
		s.outcomes[tx] = false
		return nil
	}
	delete(s.prepared, tx)
	s.outcomes[tx] = commit
	if commit {
		s.balances[l.acct] += l.delta
		s.log = append(s.log, Event{Pos: int64(len(s.log)) + 1, Acct: l.acct, Delta: l.delta, Tx: tx})
	}
	return nil
}

func (s *Shard) Balance(acct string) int64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.balances[acct]
}

func (s *Shard) Head() int64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	return int64(len(s.log))
}

func (s *Shard) Events(after int64) []Event {
	s.mu.Lock()
	defer s.mu.Unlock()
	return append([]Event(nil), s.log[after:]...)
}

func (s *Shard) SetPartitioned(v bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.partitioned = v
}

// ---------- Decision log: the coordinator's commit point ----------

// Decision is durable once recorded. Origin is the span of the original transfer,
// so that a later recovery can link back to it.
type Decision struct {
	Commit bool
	Term   Term
	Origin SpanCtx
}

type DecisionLog struct {
	mu        sync.Mutex
	records   map[TxID]Decision
	delivered map[TxID]bool
}

func NewDecisionLog() *DecisionLog {
	return &DecisionLog{records: map[TxID]Decision{}, delivered: map[TxID]bool{}}
}

// Record writes a decision only if none exists. The first decision wins, so a
// second coordinator cannot overturn one that was already recorded.
func (l *DecisionLog) Record(tx TxID, d Decision) Decision {
	l.mu.Lock()
	defer l.mu.Unlock()
	if prior, ok := l.records[tx]; ok {
		return prior
	}
	l.records[tx] = d
	return d
}

func (l *DecisionLog) Get(tx TxID) (Decision, bool) {
	l.mu.Lock()
	defer l.mu.Unlock()
	d, ok := l.records[tx]
	return d, ok
}

func (l *DecisionLog) MarkDelivered(tx TxID) {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.delivered[tx] = true
}

func (l *DecisionLog) Undelivered() []TxID {
	l.mu.Lock()
	defer l.mu.Unlock()
	var out []TxID
	for tx := range l.records {
		if !l.delivered[tx] {
			out = append(out, tx)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i] < out[j] })
	return out
}

// ---------- Coordinator ----------

type Coordinator struct {
	name         string
	term         Term
	log          *DecisionLog
	shards       map[string]*Shard
	shardOrder   []string
	owner        map[string]string // account -> shard name
	tracer       *Tracer
	afterPrepare func() // fault-injection hook used by the scenario
}

// remaining is the time left before the caller's deadline.
func remaining(ctx context.Context) time.Duration {
	if d, ok := ctx.Deadline(); ok {
		return time.Until(d)
	}
	return 24 * time.Hour
}

// Transfer runs two-phase commit. The decision is recorded before any shard is
// told to commit, so the outcome is fixed even if this coordinator fails while
// delivering it.
func (c *Coordinator) Transfer(ctx context.Context, tx TxID, from, to string, amount int64, parent SpanCtx) error {
	span := c.tracer.Start("transfer", parent)
	defer span.End()
	span.Attr("tx", string(tx))

	if remaining(ctx) < minAttempt {
		span.Outcome("deadline")
		return ErrDeadline
	}
	if d, decided := c.log.Get(tx); decided {
		// Decided by an earlier attempt: finish delivery, change nothing else.
		return c.deliver(ctx, tx, d, span)
	}
	commit, err := c.prepareBoth(tx, from, to, amount, span)
	if err != nil {
		span.Outcome("superseded")
		return err
	}
	d := c.log.Record(tx, Decision{Commit: commit, Term: c.term, Origin: span.Ctx})
	return c.deliver(ctx, tx, d, span)
}

func (c *Coordinator) prepareBoth(tx TxID, from, to string, amount int64, span *Span) (bool, error) {
	legs := []struct {
		acct  string
		delta int64
	}{{from, -amount}, {to, amount}}
	for _, l := range legs {
		shard := c.shards[c.owner[l.acct]]
		err := shard.Prepare(tx, c.term, l.acct, l.delta)
		switch {
		case errors.Is(err, ErrStaleTerm):
			return false, err
		case err != nil:
			span.Event(fmt.Sprintf("prepare refused on %s: %v", shard.name, err))
			return false, nil
		}
	}
	if c.afterPrepare != nil {
		c.afterPrepare()
	}
	return true, nil
}

// deliver sends the recorded decision to every shard. An unreachable shard leaves
// the transfer pending. The decision stays durable, and Recover finishes it later.
func (c *Coordinator) deliver(ctx context.Context, tx TxID, d Decision, span *Span) error {
	unreachable := false
	for _, name := range c.shardOrder {
		if ctx.Err() != nil {
			unreachable = true
			break
		}
		err := c.shards[name].Decide(tx, c.term, d.Commit)
		switch {
		case errors.Is(err, ErrStaleTerm):
			span.Event(fmt.Sprintf("decide refused on %s: %v", name, err))
			span.Outcome("refused")
			return err
		case err != nil:
			span.Event(fmt.Sprintf("decide pending on %s: %v", name, err))
			unreachable = true
		}
	}
	if unreachable {
		span.Outcome("pending")
		return ErrPending
	}
	c.log.MarkDelivered(tx)
	span.Outcome(map[bool]string{true: "committed", false: "aborted"}[d.Commit])
	return nil
}

// Recover re-delivers every decision not yet confirmed by all shards, under this
// coordinator's term. Each recovery is its own trace, linked to the transfer it finishes.
func (c *Coordinator) Recover(ctx context.Context) (int, error) {
	resolved := 0
	for _, tx := range c.log.Undelivered() {
		d, _ := c.log.Get(tx)
		span := c.tracer.Start("recovery-deliver", SpanCtx{}, d.Origin)
		span.Attr("tx", string(tx))
		err := c.deliver(ctx, tx, d, span)
		span.End()
		if err != nil {
			return resolved, err
		}
		resolved++
	}
	return resolved, nil
}

// ---------- Projection ----------

// Statement is a read model. Its balances and per-shard checkpoints are replaced
// together, so a failed catch-up leaves both where they were.
type Statement struct {
	mu         sync.Mutex
	checkpoint map[string]int64
	balance    map[string]int64
}

func NewStatement() *Statement {
	return &Statement{checkpoint: map[string]int64{}, balance: map[string]int64{}}
}

func (p *Statement) Catch(shards map[string]*Shard, order []string) (int, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	cp := make(map[string]int64, len(p.checkpoint))
	for k, v := range p.checkpoint {
		cp[k] = v
	}
	bal := make(map[string]int64, len(p.balance))
	for k, v := range p.balance {
		bal[k] = v
	}
	applied := 0
	for _, name := range order {
		for _, e := range shards[name].Events(cp[name]) {
			if e.Pos != cp[name]+1 {
				return 0, ErrGap
			}
			bal[e.Acct] += e.Delta
			cp[name] = e.Pos
			applied++
		}
	}
	p.checkpoint, p.balance = cp, bal
	return applied, nil
}

// Balance answers only once the projection has reached minPos on the shard that
// produced the customer's own write.
func (p *Statement) Balance(acct, shard string, minPos int64) (int64, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.checkpoint[shard] < minPos {
		return 0, ErrNotCaughtUp
	}
	return p.balance[acct], nil
}

// Verify gates cutover. Each shard's balance is compared with a fold of its own
// event log, which is a separate computation, and with the projection.
func Verify(shards map[string]*Shard, order []string, owner map[string]string, p *Statement) []string {
	p.mu.Lock()
	defer p.mu.Unlock()
	var problems []string
	folded := map[string]int64{}
	for _, name := range order {
		s := shards[name]
		if head := s.Head(); p.checkpoint[name] != head {
			problems = append(problems, fmt.Sprintf("%s: checkpoint %d != head %d", name, p.checkpoint[name], head))
		}
		for _, e := range s.Events(0) {
			folded[e.Acct] += e.Delta
		}
	}
	accts := make([]string, 0, len(owner))
	for a := range owner {
		accts = append(accts, a)
	}
	sort.Strings(accts)
	for _, a := range accts {
		auth := shards[owner[a]].Balance(a)
		if folded[a] != auth {
			problems = append(problems, fmt.Sprintf("%s: replay %d != shard %d", a, folded[a], auth))
		}
		if p.balance[a] != auth {
			problems = append(problems, fmt.Sprintf("%s: projection %d != shard %d", a, p.balance[a], auth))
		}
	}
	return problems
}

// ---------- Scenario ----------

func verdict(err error) string {
	if err == nil {
		return "ok"
	}
	return err.Error()
}

func main() {
	tracer := &Tracer{}
	decisions := NewDecisionLog()
	shardA := NewShard("A", map[string]int64{"merchant-17": 50000})
	shardB := NewShard("B", map[string]int64{"merchant-42": 12000})
	shards := map[string]*Shard{"A": shardA, "B": shardB}
	order := []string{"A", "B"}
	owner := map[string]string{"merchant-17": "A", "merchant-42": "B"}

	// Two coordinators share the decision log. coord-1 is the authority before the
	// failover; coord-2 takes over at a higher term.
	coord1 := &Coordinator{name: "coord-1", term: 12, log: decisions, shards: shards, shardOrder: order, owner: owner, tracer: tracer}
	coord2 := &Coordinator{name: "coord-2", term: 13, log: decisions, shards: shards, shardOrder: order, owner: owner, tracer: tracer}

	policy := Policy{
		idPayments:    {"transfer.start": true, "statement.read": true},
		idCoordinator: {"prepare": true, "decide": true},
		idReporting:   {"statement.read": true},
	}

	fmt.Println("== 1. identity and policy")
	fmt.Println("payments transfer.start:", verdict(policy.Authorize(idPayments, "transfer.start")))
	fmt.Println("reporting decide:", verdict(policy.Authorize(idReporting, "decide")))

	fmt.Println("== 2. request enters with trace context")
	root := tracer.Start("POST /transfers", SpanCtx{})
	header := root.Ctx.Traceparent()
	inbound, err := ParseTraceparent(header)
	fmt.Printf("traceparent: %s parsed=%v same-trace=%v\n", header, err == nil, inbound.Trace == root.Ctx.Trace)

	ctx, cancel := context.WithTimeout(context.Background(), userDeadline)
	defer cancel()

	fmt.Println("== 3. happy path: two-phase transfer across shards")
	fmt.Println("tx-9010:", verdict(coord1.Transfer(ctx, "tx-9010", "merchant-17", "merchant-42", 2000, inbound)))
	fmt.Printf("balances: merchant-17=%d merchant-42=%d\n", shardA.Balance("merchant-17"), shardB.Balance("merchant-42"))

	fmt.Println("== 4. repeated command is idempotent")
	fmt.Println("tx-9010 again:", verdict(coord1.Transfer(ctx, "tx-9010", "merchant-17", "merchant-42", 2000, inbound)))
	fmt.Printf("balances: merchant-17=%d merchant-42=%d\n", shardA.Balance("merchant-17"), shardB.Balance("merchant-42"))

	fmt.Println("== 5. shard B partitioned after both prepares")
	coord1.afterPrepare = func() { shardB.SetPartitioned(true) }
	fmt.Println("tx-9011:", verdict(coord1.Transfer(ctx, "tx-9011", "merchant-17", "merchant-42", 1500, inbound)))
	coord1.afterPrepare = nil
	d, _ := decisions.Get("tx-9011")
	fmt.Printf("decision durable: commit=%v term=%d\n", d.Commit, d.Term)
	fmt.Printf("balances while pending: merchant-17=%d merchant-42=%d\n", shardA.Balance("merchant-17"), shardB.Balance("merchant-42"))

	proj := NewStatement()
	n, err := proj.Catch(shards, order)
	fmt.Printf("projection catch-up: applied=%d err=%v\n", n, err)
	_, err = proj.Balance("merchant-42", "B", 3)
	fmt.Println("read merchant-42 at B>=3:", verdict(err))
	bal, err := proj.Balance("merchant-17", "A", 3)
	fmt.Printf("read merchant-17 at A>=3: %d err=%v\n", bal, err)

	fmt.Println("== 6. failover: coord-2 recovers at term 13")
	shardB.SetPartitioned(false)
	resolved, err := coord2.Recover(ctx)
	fmt.Printf("recovered=%d err=%v\n", resolved, err)
	fmt.Printf("balances: merchant-17=%d merchant-42=%d\n", shardA.Balance("merchant-17"), shardB.Balance("merchant-42"))
	if rec := findSpan(tracer, "recovery-deliver"); rec != nil {
		fmt.Printf("recovery span: links=%d linked-to-request=%v own-trace=%v\n",
			len(rec.Links), rec.Links[0].Trace == inbound.Trace, rec.Ctx.Trace != inbound.Trace)
	}

	fmt.Println("== 7. stale coord-1 tries to redeliver at term 12")
	fmt.Println("tx-9011 via coord-1:", verdict(coord1.Transfer(ctx, "tx-9011", "merchant-17", "merchant-42", 1500, inbound)))
	fmt.Printf("balances: merchant-17=%d merchant-42=%d\n", shardA.Balance("merchant-17"), shardB.Balance("merchant-42"))

	fmt.Println("== 8. projection catches up; verification gates cutover")
	n, err = proj.Catch(shards, order)
	fmt.Printf("catch-up applied=%d err=%v\n", n, err)
	bal, err = proj.Balance("merchant-42", "B", 3)
	fmt.Printf("read merchant-42 at B>=3: %d err=%v\n", bal, err)
	if problems := Verify(shards, order, owner, proj); len(problems) == 0 {
		fmt.Println("verification: passed, cutover allowed")
	} else {
		for _, p := range problems {
			fmt.Println("verification problem:", p)
		}
	}

	fmt.Println("== 9. deadline too short for an attempt")
	shortCtx, stop := context.WithTimeout(context.Background(), 10*time.Millisecond)
	defer stop()
	fmt.Println("tx-9012:", verdict(coord2.Transfer(shortCtx, "tx-9012", "merchant-42", "merchant-17", 100, inbound)))

	root.Outcome("completed")
	root.End()
	fmt.Println("== 10. finished spans")
	for _, s := range tracer.finished {
		fmt.Printf("%-18s tx=%-8s result=%-10s links=%d\n", s.Name, s.Attrs["tx"], s.Result(), len(s.Links))
	}
}
